select case when duration_sec >= 528 then 'high' when duration_sec >= 208 then 'mid' else 'low' end as duration_sec_bucket, sum(duration_sec) as total_duration_sec, rank() over (order by sum(duration_sec) desc) as duration_sec_rank from web_events where hour(event_time) between 7 and 11 group by case when duration_sec >= 528 then 'high' when duration_sec >= 208 then 'mid' else 'low' end order by duration_sec_rank
